gpu_device_preflight_command:
PYTHONPATH=. python3 - "{run_root}" <<'PY'
import json, sys
from pathlib import Path

run_root = Path(sys.argv[1])
prelaunch = run_root / 'prelaunch'
prelaunch.mkdir(parents=True, exist_ok=True)
failures = []
try:
    import torch
except Exception as exc:
    failures.append(f'torch_import:{exc}')
    torch = None
device_name = None
if torch is not None and torch.cuda.is_available():
    device_name = torch.cuda.get_device_name(0)
else:
    failures.append('cuda_unavailable')
if device_name:
    lower = device_name.lower()
    if '1070' in lower:
        failures.append('audit_lane_gtx_1070_forbidden')
    if '4070' not in lower and 'laptop' not in lower:
        failures.append(f'unexpected_gpu:{device_name}')
receipt = {'schema': 'hrm_text_158_slice5_gpu_device_preflight/v1', 'device_name': device_name, 'pass': not failures, 'failures': failures}
out = prelaunch / 'gpu_device_preflight_receipt.json'
out.write_text(json.dumps(receipt, indent=2, sort_keys=True) + '\n', encoding='utf-8')
if failures:
    raise SystemExit(1)
print(json.dumps(receipt, indent=2))
PY

live_carrier_scale_smoke_receipt_command:
PYTHONPATH=. python3 - "{run_root}" <<'PY'
import json, sys
from collections import defaultdict
from pathlib import Path

run_root = Path(sys.argv[1])
prelaunch = run_root / 'prelaunch'
prelaunch.mkdir(parents=True, exist_ok=True)
failures = []

classifier_path = prelaunch / 'milestone_stall_classifier_receipt.json'
if not classifier_path.is_file():
    failures.append('missing_milestone_stall_classifier_receipt')
    classifier = {}
else:
    classifier = json.loads(classifier_path.read_text(encoding='utf-8'))

classifier_classification = classifier.get('classification', 'MISSING')
stalled_sub_phase_id = classifier.get('stalled_sub_phase_id')
stalled_parent_phase_id = classifier.get('stalled_parent_phase_id')

baseline_rc = int((prelaunch / 'baseline_launch_rc.txt').read_text().strip()) if (prelaunch / 'baseline_launch_rc.txt').is_file() else None
instr_rc = int((prelaunch / 'instrumented_launch_rc.txt').read_text().strip()) if (prelaunch / 'instrumented_launch_rc.txt').is_file() else None

base_path = run_root / 'baseline_snapshot_off' / 'receipt.json'
instr_path = run_root / 'instrumented_snapshot_on' / 'receipt.json'
if not base_path.is_file():
    failures.append('missing_baseline_receipt')
if not instr_path.is_file():
    failures.append('missing_instrumented_receipt')
base = json.loads(base_path.read_text()) if base_path.is_file() else {}
instr = json.loads(instr_path.read_text()) if instr_path.is_file() else {}

for label, receipt in (('baseline', base), ('instrumented', instr)):
    if receipt and not receipt.get('persistent_accumulator_event_coded_live'):
        failures.append(f'{label}_missing_persistent_accumulator_event_coded_live')
if instr.get('d_live_carrier_snapshot_enabled') is not True:
    failures.append('instrumented_missing_d_live_carrier_snapshot_enabled')
if base.get('d_live_carrier_snapshot_enabled'):
    failures.append('baseline_had_snapshot_enabled')

base_steps = base.get('step_reports') or {}
instr_steps = instr.get('step_reports') or {}
deltas = {}
for key in sorted(set(base_steps) | set(instr_steps), key=lambda x: int(x)):
    b, i = base_steps.get(key) or {}, instr_steps.get(key) or {}
    if 'duration_seconds' in b and 'duration_seconds' in i:
        deltas[key] = float(i['duration_seconds']) - float(b['duration_seconds'])

jsonl_path = run_root / 'instrumented_snapshot_on' / 'd_recompute_window_diagnostic' / 'live_carrier_snapshot.jsonl'
rows_by_step = defaultdict(list)
if jsonl_path.is_file():
    for line in jsonl_path.read_text(encoding='utf-8').splitlines():
        if line.strip():
            rows_by_step[int(json.loads(line)['step'])].append(json.loads(line))
else:
    failures.append('missing_live_carrier_snapshot_jsonl')

total_rows = sum(len(v) for v in rows_by_step.values())
classification = 'PASS_COST_CHARACTERIZED'

c8_baseline = int((base.get('bounded_delta_global_summary') or {}).get('C8_TRANSIENT_DENSE_COMPUTE_NUMEL') or (base.get('global_summary') or {}).get('C8_TRANSIENT_DENSE_COMPUTE_NUMEL') or 0)
sparse_auth_baseline = (base.get('bounded_delta_global_summary') or {}).get('event_coded_sparse_vote_authority')
if c8_baseline > 0:
    failures.append(f'baseline_c8_transient_dense_{c8_baseline}')
if sparse_auth_baseline is not True:
    failures.append(f'baseline_sparse_authority_not_true:{sparse_auth_baseline!r}')

peak_emit_delta = max(deltas.values()) if deltas else None
FEASIBLE_PEAK = 5.0
emit_too_expensive = peak_emit_delta is not None and peak_emit_delta > FEASIBLE_PEAK

steps_completed_base = int(base.get('steps_completed') or 0)
steps_completed_instr = int(instr.get('steps_completed') or 0)
baseline_clean = (baseline_rc in (0, None)) and steps_completed_base >= 10
instrumented_clean = (instr_rc in (0, None)) and steps_completed_instr >= 10
if baseline_rc not in (0, None):
    failures.append(f'baseline_launch_rc_{baseline_rc}')
if instr_rc not in (0, None):
    failures.append(f'instrumented_launch_rc_{instr_rc}')

if classifier_classification == 'LIVENESS_FAIL_KERNELIZED_BUT_STALLED':
    classification = 'LIVENESS_FAIL_KERNELIZED_BUT_STALLED'
elif classifier_classification == 'SUBMILESTONE_INSTRUMENTATION_INVALID':
    classification = 'SUBMILESTONE_INSTRUMENTATION_INVALID'
elif classifier_classification == 'LIVENESS_FAIL_TOTAL_TIMEOUT':
    classification = 'LIVENESS_FAIL_TOTAL_TIMEOUT'
elif not baseline_clean or c8_baseline > 0 or sparse_auth_baseline is not True:
    classification = 'LIVENESS_FAIL'
elif total_rows == 0:
    failures.append('SMOKE_INVALID_NO_EVENT_CODED_CARRIER')
    classification = 'SMOKE_INVALID_NO_EVENT_CODED_CARRIER'
else:
    steps_completed = int(instr.get('steps_completed') or 0)
    for step in range(1, steps_completed + 1):
        if len(rows_by_step.get(step, [])) < 1:
            failures.append(f'zero_rows_step_{step}')
            classification = 'SMOKE_INVALID_NO_EVENT_CODED_CARRIER'
    if classification != 'SMOKE_INVALID_NO_EVENT_CODED_CARRIER':
        if not instrumented_clean:
            classification = 'SMOKE_INSTRUMENTED_TIMEOUT_POSSIBLE_EMIT_OVERHEAD'
        elif emit_too_expensive:
            classification = 'EMIT_PATH_TOO_EXPENSIVE'
        elif peak_emit_delta is not None and peak_emit_delta <= FEASIBLE_PEAK and total_rows > 0:
            classification = 'EMIT_FEASIBLE_FOR_STEP2B_SCALE_SMOKE'
        else:
            classification = 'PASS_COST_CHARACTERIZED'

receipt = {
    'schema': 'hrm_text_158_slice5_live_carrier_gpu_scale_smoke_receipt/v1',
    'packet_revision': 'v6_re_m4_post_submilestone_emit',
    'm4_mode': 're_M4_post_submilestone_emit',
    'run_id': '2189e72023',
    'classifier_classification': classifier_classification,
    'stalled_sub_phase_id': stalled_sub_phase_id,
    'stalled_parent_phase_id': stalled_parent_phase_id,
    'baseline_launch_rc': baseline_rc,
    'instrumented_launch_rc': instr_rc,
    'persistent_accumulator_event_coded_live_baseline': base.get('persistent_accumulator_event_coded_live'),
    'persistent_accumulator_event_coded_live_instrumented': instr.get('persistent_accumulator_event_coded_live'),
    'total_live_carrier_snapshot_rows': total_rows,
    'emit_rows_per_step': {str(k): len(v) for k, v in sorted(rows_by_step.items())},
    'per_step_duration_delta_seconds': deltas,
    'peak_per_step_emit_delta_seconds': peak_emit_delta,
    'classification': classification,
    'emit_too_expensive': bool(emit_too_expensive),
    'pass': not failures and classification in (
        'EMIT_FEASIBLE_FOR_STEP2B_SCALE_SMOKE',
        'EMIT_PATH_TOO_EXPENSIVE',
        'PASS_COST_CHARACTERIZED',
    ),
    'failures': failures,
}
out = prelaunch / 'live_carrier_scale_smoke_receipt.json'
out.write_text(json.dumps(receipt, indent=2, sort_keys=True) + '\n', encoding='utf-8')
print(json.dumps(receipt, indent=2))
if failures and classification not in (
    'LIVENESS_FAIL_KERNELIZED_BUT_STALLED',
    'SUBMILESTONE_INSTRUMENTATION_INVALID',
    'LIVENESS_FAIL',
    'LIVENESS_FAIL_TOTAL_TIMEOUT',
):
    raise SystemExit(1)
PY

milestone_stall_classifier_command:
PYTHONPATH=. python3 - "{run_root}" <<'PY'
import json, sys
from pathlib import Path

run_root = Path(sys.argv[1])
prelaunch = run_root / 'prelaunch'
prelaunch.mkdir(parents=True, exist_ok=True)
PHASES = ['step_forward_backward','sparse_vote_construction','sparse_cap_apply','live_carrier_snapshot_emit','artifact_flush']
BUDGETS = {'step_forward_backward':90,'sparse_vote_construction':120,'sparse_cap_apply':180,'live_carrier_snapshot_emit':60,'artifact_flush':60}
SUB_PHASES = [
    ('cap_selection_cpu_copy', 'sparse_cap_apply_cap_selection_cpu_copy.jsonl', 45),
    ('post_cap_apply_sync', 'sparse_cap_apply_post_cap_apply_sync.jsonl', 120),
    ('boundary_normalize', 'sparse_cap_apply_boundary_normalize.jsonl', 45),
]
failures = []
stall_hits = []
instrumentation_invalid = []
stalled_sub_phase_id = None
stalled_parent_phase_id = None

def cuda_available():
    try:
        import torch
        return bool(torch.cuda.is_available())
    except Exception:
        return False

cuda = cuda_available()

for arm in ('baseline_snapshot_off','instrumented_snapshot_on'):
    scratch = run_root / arm
    receipt_path = scratch / 'receipt.json'
    receipt = json.loads(receipt_path.read_text()) if receipt_path.is_file() else {}
    sparse_auth = bool((receipt.get('bounded_delta_global_summary') or {}).get('event_coded_sparse_vote_authority'))
    parent_sparse_cap_path = scratch / 'liveness_milestones' / 'sparse_cap_apply.jsonl'
    parent_sparse_cap_lines = []
    if parent_sparse_cap_path.is_file():
        parent_sparse_cap_lines = [ln for ln in parent_sparse_cap_path.read_text(encoding='utf-8').splitlines() if ln.strip()]
    parent_sparse_cap_complete = len(parent_sparse_cap_lines) > 0

    for phase_id in PHASES:
        if phase_id == 'live_carrier_snapshot_emit' and arm == 'baseline_snapshot_off':
            continue
        path = scratch / 'liveness_milestones' / f'{phase_id}.jsonl'
        if not path.is_file():
            if phase_id == 'sparse_cap_apply' and sparse_auth and cuda:
                stall_hits.append({'arm': arm, 'phase_id': phase_id, 'reason': 'missing_parent_sparse_cap_jsonl'})
            else:
                failures.append(f'missing_milestone_jsonl:{arm}:{phase_id}')
            continue
        lines = [ln for ln in path.read_text(encoding='utf-8').splitlines() if ln.strip()]
        if not lines:
            failures.append(f'empty_milestone_jsonl:{arm}:{phase_id}')
            continue
        counters = []
        for ln in lines:
            row = json.loads(ln)
            if row.get('schema') != 'hrm_text_158_phase_milestone_counter/v1':
                instrumentation_invalid.append({'arm': arm, 'phase_id': phase_id, 'reason': 'bad_schema'})
                continue
            counters.append(int(row.get('milestone_counter', -1)))
        for i in range(1, len(counters)):
            if counters[i] < counters[i-1]:
                instrumentation_invalid.append({'arm': arm, 'phase_id': phase_id, 'reason': 'non_monotonic'})
        elapsed = []
        for ln in lines:
            row = json.loads(ln)
            if 'elapsed_since_phase_enter_seconds' in row:
                elapsed.append(float(row['elapsed_since_phase_enter_seconds']))
        if elapsed and counters and (max(elapsed) - min(elapsed)) >= BUDGETS[phase_id] and max(counters) == min(counters):
            stall_hits.append({'arm': arm, 'phase_id': phase_id, 'budget': BUDGETS[phase_id], 'reason': 'parent_phase_flat_counter'})

    if sparse_auth and cuda:
        for sub_id, jsonl_name, sub_budget in SUB_PHASES:
            sub_path = scratch / 'liveness_milestones' / jsonl_name
            if not sub_path.is_file():
                if parent_sparse_cap_path.is_file() or not parent_sparse_cap_complete:
                    stall_hits.append({'arm': arm, 'sub_phase_id': sub_id, 'reason': 'pre_first_marker_absent', 'budget': sub_budget})
                    if stalled_sub_phase_id is None:
                        stalled_sub_phase_id = sub_id
                        stalled_parent_phase_id = 'sparse_cap_apply'
                elif parent_sparse_cap_complete:
                    instrumentation_invalid.append({'arm': arm, 'sub_phase_id': sub_id, 'reason': 'missing_after_parent_complete'})
                continue
            sub_lines = [ln for ln in sub_path.read_text(encoding='utf-8').splitlines() if ln.strip()]
            if not sub_lines:
                if not parent_sparse_cap_complete:
                    stall_hits.append({'arm': arm, 'sub_phase_id': sub_id, 'reason': 'empty_pre_first_marker', 'budget': sub_budget})
                    if stalled_sub_phase_id is None:
                        stalled_sub_phase_id = sub_id
                        stalled_parent_phase_id = 'sparse_cap_apply'
                else:
                    instrumentation_invalid.append({'arm': arm, 'sub_phase_id': sub_id, 'reason': 'empty_after_parent_complete'})
                continue
            sub_counters = []
            for ln in sub_lines:
                row = json.loads(ln)
                if row.get('schema') != 'hrm_text_158_phase_milestone_counter/v1':
                    instrumentation_invalid.append({'arm': arm, 'sub_phase_id': sub_id, 'reason': 'bad_schema'})
                    continue
                sub_counters.append(int(row.get('milestone_counter', -1)))
            sub_elapsed = [float(json.loads(ln).get('elapsed_since_phase_enter_seconds', 0)) for ln in sub_lines if 'elapsed_since_phase_enter_seconds' in json.loads(ln)]
            if sub_elapsed and sub_counters and (max(sub_elapsed) - min(sub_elapsed)) >= sub_budget and max(sub_counters) == min(sub_counters):
                stall_hits.append({'arm': arm, 'sub_phase_id': sub_id, 'reason': 'sub_phase_flat_counter', 'budget': sub_budget})
                if stalled_sub_phase_id is None:
                    stalled_sub_phase_id = sub_id
                    stalled_parent_phase_id = 'sparse_cap_apply'

classification = 'PASS_MILESTONE_REPLAY'
if instrumentation_invalid and not stall_hits:
    classification = 'SUBMILESTONE_INSTRUMENTATION_INVALID'
elif stall_hits:
    classification = 'LIVENESS_FAIL_KERNELIZED_BUT_STALLED'
elif failures:
    classification = 'MILESTONE_ARTIFACT_INCOMPLETE'

receipt = {
    'schema': 'hrm_text_158_slice5_milestone_stall_classifier_receipt/v2',
    'packet_revision': 'v6_re_m4_post_submilestone_emit',
    'classification': classification,
    'stall_hits': stall_hits,
    'instrumentation_invalid': instrumentation_invalid,
    'stalled_sub_phase_id': stalled_sub_phase_id,
    'stalled_parent_phase_id': stalled_parent_phase_id,
    'cuda_available': cuda,
    'pass': classification == 'PASS_MILESTONE_REPLAY',
    'failures': failures,
}
out = prelaunch / 'milestone_stall_classifier_receipt.json'
out.write_text(json.dumps(receipt, indent=2, sort_keys=True) + '\n', encoding='utf-8')
print(json.dumps(receipt, indent=2))
if classification != 'PASS_MILESTONE_REPLAY':
    raise SystemExit(1)
PY
